-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- 4 · THE REMEDIATION REPORT — counts only, no ids, no addresses, no estate names
-- ────────────────────────────────────────────────────────────────────────────────────────────────
--
-- ★ HOW MUCH WORK PHASE C HAS TO DO ON THE DAY IT LANDS. A NOTICE rather than an assertion: a
-- non-zero remediable population is not an error, it is the operator's queue. It is printed here so
-- the number is known at paste time rather than discovered from the console.
do $$
declare
  v_failed    bigint;
  v_uncertain bigint;
  v_legacy    bigint;
  v_renotices bigint;
begin
  select
    count(*) filter (where o.status = 'failedPermanent'),
    count(*) filter (where o.status = 'outcomeUncertain'),
    count(*) filter (where o.status = 'dispatched' and o.notice_accepted_at is null),
    count(*) filter (where o.notice_kind = 'death_process.window_renotice')
    into v_failed, v_uncertain, v_legacy, v_renotices
    from public.owner_notice_outbox o
   where o.superseded_by is null
     and o.channel = 'email';

  raise notice '0059 REMEDIATION CENSUS · current generations eligible for re-notice: '
    'failedPermanent=% · outcomeUncertain=% · dispatched-with-no-acceptance-fact=% · '
    're-notices already issued=%', v_failed, v_uncertain, v_legacy, v_renotices;
  raise notice '0059 NOTE · a re-notice QUEUES a new warning. It is not an acceptance, not a '
    'delivery, and not a statement that the owner has been reached — only the providerAccepted '
    'settlement path may ever stamp notice_accepted_at.';
end $$;


-- ==== db/functions/owner_notice_reissue.sql =======================================================
-- ════════════════════════════════════════════════════════════════════════════════════════════════
-- PHASE 11-OC · PHASE C — THE OPERATOR RE-NOTICE, AND THE ONE PLACE ITS ELIGIBILITY IS DECIDED
-- ════════════════════════════════════════════════════════════════════════════════════════════════
--
-- ★ WHAT THIS FILE OWNS.
--
--   owner_notice_episode_kinds()          the kind SET that constitutes one episode   [INTERNAL]
--   owner_notice_reissue_kind()           the kind a re-notice takes                  [INTERNAL]
--   owner_notice_reissue_assessment()     may this episode be re-noticed, and why not [INTERNAL]
--   reissue_owner_safety_notice()         the operator door                [admin, AAL2 + fresh]
--
-- ★ THE ASSESSMENT IS A SEPARATE FUNCTION FOR ONE REASON, AND IT IS NOT TIDINESS. The operator
-- console must show "Re-send owner safety notice" exactly when the door would accept it. Any second
-- opinion — a TypeScript mirror, a status list in a projection, a `case` expression in the case file
-- — is a policy that drifts, and the failure mode is an operator clicking a control the server then
-- refuses, or (worse) a control hidden on an estate that genuinely needs remediating. So the
-- projection and the door call the SAME function, and `db/tests/release_safety_authorization.sql`
-- §11 asserts they agree on every fixture rather than assuming they must.
--
-- ★ A RE-NOTICE IS AN APPEND, NEVER A RESET. It writes a NEW row and retires the previous one with a
-- pointer. Nothing about the predecessor is rewritten — not `requested_at`, not `attempts`, not
-- `failure_class`, not `dispatched_at`, not `notice_accepted_at`, not `case_id`, not `generation`.
-- That evidence is WHY the reissue was warranted, and an operator reconstructing a disputed release a
-- year later needs to see the failure that prompted it, not a row that was quietly returned to the
-- queue. Requeuing a terminal row would also destroy the one signal that distinguishes an accidental
-- retry from a deliberate second warning (see IDEMPOTENCY below).
--
-- ★ IT IS PROTECTIVE, SO IT IS NOT A TWO-PERSON ACT. `authorize_release` requires two distinct
-- reviewers because it DISCLOSES an estate irreversibly. A re-notice discloses nothing: it queues a
-- message telling a possibly-living owner that a process is running against their estate, which is
-- the control that protects them. Requiring a second operator would make the protective act harder
-- than the harmful one — and the whole D7 monotonicity property is that issuing a notice can only
-- ever ADD safety. It is nevertheless admin-gated, AAL2, freshness-bound, reason-required and fully
-- audited, because an operator who could queue mail at will is an operator who could mail a living
-- person repeatedly.
--
-- ★ WHAT A SUCCESSFUL CALL MEANS, STATED SO NOTHING DOWNSTREAM CAN RENAME IT:
--
--        NEW WARNING QUEUED.
--
--   It is NOT "the owner was warned", NOT "the provider accepted", NOT "delivered". The new row
--   starts `queued` with `notice_accepted_at` NULL and only `record_owner_notice_outcome`'s
--   `providerAccepted` branch may ever stamp it. Reissuing creates no acceptance authority
--   whatsoever, which is exactly why an operator cannot use this door to unblock a release.
--
-- ★ IDEMPOTENCY, AND THE DISTINCTION IT ENCODES. `lib/ownerNotices/drain.ts` builds the provider
-- Idempotency-Key from the ROW id (`afterworth/owner-notice/<id>`). A reclaim or a retry within one
-- generation therefore replays the SAME key — the provider is asked to no-op a repeat. A deliberate
-- re-notice is a new row with a new id, so it carries a NEW key and is a genuinely new message.
--
--        ACCIDENTAL RETRY   → same idempotency domain
--        DELIBERATE REISSUE → new idempotency domain
--
--   That distinction is a property of the id, not of a flag anybody remembers to set. Delivery
--   semantics remain AT-LEAST-ONCE; no provider exactly-once behaviour is claimed anywhere.
--
-- ★ AND THE OWNER IS TOLD NOTHING NEW. The email template takes only a link — no kind, no
-- generation, no attempt count, no failure class. The second message is byte-identical to the first.
-- Internal state is not user copy, and on this channel that rule is sharper than usual.
--
-- Source of truth — re-apply on DB reset. Deploys via `db/bundles/owner_notice_reissue_bundle.sql`,
-- after migration 0059.

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- owner_notice_episode_kinds() → text[]                                                [INTERNAL]
-- ────────────────────────────────────────────────────────────────────────────────────────────────
--
-- ★ THE EPISODE IS A SET OF KINDS, AND IT IS DEFINED EXACTLY ONCE. Phase A wrote
-- `notice_kind = 'death_process.window_opened'` as a literal in the readiness census, in migration
-- 0058's blast-radius report, and in the partial unique index. The moment a re-notice takes a second
-- kind, every one of those literals becomes a filter that CANNOT SEE THE REMEDY: a remediated estate
-- would keep reporting as refused, its acceptance would never be counted, and the instrument built to
-- measure the Phase D blast radius would be blind to the mechanism built to shrink it.
--
-- A function rather than three copies, for the reason `owner_notice_claim_visibility()` gives: two
-- literals are two opinions about the same bytes, and the first time they drift the census stops
-- describing what the door actually does.
--
-- `immutable` because the vocabulary is a compile-time constant of this deployment, not a row.
create or replace function public.owner_notice_episode_kinds()
 returns text[]
 language sql
 immutable
 set search_path to 'public'
as $function$
  select array['death_process.window_opened', 'death_process.window_renotice']::text[];
$function$;
revoke execute on function public.owner_notice_episode_kinds() from public, anon, authenticated;

comment on function public.owner_notice_episode_kinds() is
  'The owner-safety notice kinds that constitute ONE episode (Phase 11-OC / Phase C): the initial '
  'window-opened dispatch and every deliberate operator re-notice. Single-sourced so the readiness '
  'census, the operator projection and the re-notice routine cannot disagree about which rows belong '
  'to the episode — a literal in any one of them would make the remedy invisible to the instrument '
  'that measures whether the remedy worked. INTERNAL: no client role may read the vocabulary.';

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- owner_notice_reissue_kind() → text                                                   [INTERNAL]
-- ────────────────────────────────────────────────────────────────────────────────────────────────
--
-- ★ A RE-NOTICE IS NOT THE WINDOW OPENING. `death_process.window_opened` records a lifecycle
-- transition that happened once, at a specific instant, and stamped `owner_notified_at`. A second row
-- carrying that kind would make the outbox assert the window opened twice — a false statement about
-- the state machine, in the table an investigator reads to reconstruct what the owner was told.
create or replace function public.owner_notice_reissue_kind()
 returns text
 language sql
 immutable
 set search_path to 'public'
as $function$
  select 'death_process.window_renotice'::text;
$function$;
revoke execute on function public.owner_notice_reissue_kind() from public, anon, authenticated;

comment on function public.owner_notice_reissue_kind() is
  'The notice_kind a deliberate operator re-notice takes (Phase 11-OC / Phase C). Distinct from '
  'death_process.window_opened so a second warning is never recorded as the initial window-opening '
  'event. Both kinds are members of owner_notice_episode_kinds().';

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- owner_notice_reissue_assessment(p_case) → jsonb                                      [INTERNAL]
-- ────────────────────────────────────────────────────────────────────────────────────────────────
--
-- ★ ONE POLICY, TWO CALLERS. `reissue_owner_safety_notice` acts on this verdict; the operator
-- projection renders it. Neither restates it.
--
-- ★ IT IS `stable`, WHICH IS WHY THE DOOR TAKES ITS LOCKS FIRST. A stable function reads the calling
-- statement's snapshot. Called from the projection that is a read and correct; called from the door
-- it is correct ONLY because the door has already locked the case row and the current-generation row,
-- so the state it reads cannot move between the verdict and the write. The lock order is stated at
-- the door and is part of this function's contract rather than an implementation detail of its
-- caller.
--
-- ★ EVERY REFUSAL HAS A NAME, AND THE SET IS CLOSED. A fall-through would let a future status join a
-- neighbouring bucket silently — the same nameless-gap failure the censuses are written to avoid.
-- `notice_not_reissuable` exists so a seventh status shows up as an explicit unclassified refusal.
--
-- ★ IT NEVER RETURNS AN ADDRESS. `owner_channel_resolvable` answers the operator's real question —
-- "will this succeed" — and answers "what is this living person's address" not at all. That is the
-- same trade `admin_list_death_verification_cases` already makes, for the same reason.
create or replace function public.owner_notice_reissue_assessment(p_case uuid)
 returns jsonb
 language plpgsql
 security definer
 stable
 set search_path to 'public'
as $function$
declare
  v_c          public.death_verification_cases%rowtype;
  v_state      text;
  v_canonical  uuid;
  v_row        public.owner_notice_outbox%rowtype;
  v_owner      uuid;
  v_resolvable boolean;
  v_reason     text;
  v_refusal    text;
begin
  if p_case is null then
    return jsonb_build_object('eligible', false, 'refusal_code', 'case_not_found');
  end if;

  select * into v_c from public.death_verification_cases c where c.id = p_case;
  if not found then
    return jsonb_build_object('eligible', false, 'refusal_code', 'case_not_found');
  end if;

  -- ★ THE EPISODE KEY IS RESOLVED CANONICALLY AND THE CALLER'S CASE IS COMPARED AGAINST IT — never
  -- trusted as the episode. Identical derivation to `dispatch_owner_safety_notice` and to the
  -- readiness census: the newest VERIFIED case for this estate. A historical case on the same estate
  -- is a real, reachable input (`rejected` and `cancelled` both return the lifecycle to `active`, and
  -- a later process opens a new case), and remediating a current death process using a notice from an
  -- older one is the estate-scope defect this whole phase exists to close.
  select c.id into v_canonical
    from public.death_verification_cases c
   where c.estate_id = v_c.estate_id and c.status = 'verified'
   order by c.decided_at desc
   limit 1;

  select l.state into v_state from public.estate_lifecycle l where l.estate_id = v_c.estate_id;
  v_state := coalesce(v_state, 'active');

  v_owner := public.estate_owner_user_id(v_c.estate_id);
  v_resolvable := exists (
    select 1 from auth.users u
     where u.id = v_owner and btrim(coalesce(u.email, '')) <> ''
  );

  -- The CURRENT generation of this episode: the row nothing supersedes, across BOTH episode kinds.
  select * into v_row
    from public.owner_notice_outbox o
   where o.case_id = p_case
     and o.channel = 'email'
     and o.notice_kind = any (public.owner_notice_episode_kinds())
     and o.superseded_by is null
   limit 1;

  -- ── THE REFUSAL LADDER, IN THE ORDER THE DOOR APPLIES IT ─────────────────────────────────────
  if v_canonical is null then
    v_refusal := 'no_verified_case';
  elsif v_canonical <> p_case then
    -- Covers BOTH "this is a historical case on an estate that has moved on" and "this case was
    -- never verified". The operator's next action is the same in either: work the current case.
    v_refusal := 'case_not_current';
  elsif v_state not in ('owner_notification_dispatched', 'challenge_window') then
    -- ★ THE PERMITTED STATES ARE THE TWO IN WHICH A WARNING STILL MEANS SOMETHING. Before dispatch
    -- there is nothing to re-send (the remedy is dispatch); after a halt or a release the process the
    -- notice describes is over, and mailing a living owner about a concluded process is a false alarm.
    v_refusal := 'invalid_reissue_state';
  elsif v_row.id is null then
    -- Fail closed, and deliberately NOT "dispatch instead". Creating an initial dispatch from this
    -- door would be a second, unaudited entry point into a lifecycle transition.
    v_refusal := 'no_current_notice';
  elsif v_row.status = 'queued' then
    v_refusal := 'notice_still_queued';        -- the ordinary drain still owns it
  elsif v_row.status = 'processing' then
    v_refusal := 'notice_still_processing';    -- OB-1 visibility/reclaim still owns it
  elsif v_row.status = 'dispatched' and v_row.notice_accepted_at is not null then
    v_refusal := 'notice_already_accepted';    -- provider acceptance is established; nothing to remedy
  elsif v_row.status = 'cancelled' then
    -- Defence in depth. Nothing in production writes 'cancelled'; one test fixture does, by direct
    -- UPDATE. Named anyway, because "currently unreachable" is a statement about today's code.
    v_refusal := 'notice_cancelled';
  elsif v_row.status = 'failedPermanent' then
    -- ★ THE VOCABULARY REASON IS DERIVED FROM THE PREDECESSOR, NEVER SUPPLIED. A caller-supplied
    -- value would let an operator relabel an outcomeUncertain reissue as a failed one.
    v_reason := case when v_row.failure_class = 'stale_beyond_age_gate'
                     then 'prior_stale_beyond_age_gate'
                     else 'prior_failed_permanent' end;
  elsif v_row.status = 'outcomeUncertain' then
    v_reason := 'prior_outcome_uncertain';
  elsif v_row.status = 'dispatched' and v_row.notice_accepted_at is null then
    -- ★ THE LEGACY CLASS, AND IT IS LOAD-BEARING. `dispatched` is NOT proof of the Phase A acceptance
    -- fact: every row written before Phase A carries that status with a NULL stamp, because the
    -- stamp did not exist. Refusing this class on the strength of its status would leave exactly the
    -- population Phase D blocks with no route to a remedy — which is the reason Phase C precedes D.
    -- It is structurally unreachable for rows written AFTER Phase A (status and acceptance are set in
    -- one UPDATE), so a row in this shape is an unambiguous pre-Phase-A marker.
    v_reason := 'legacy_no_acceptance_record';
  else
    -- NOT a fall-through: a status outside the six lands here BY NAME, so a widened CHECK constraint
    -- shows up as an explicit refusal instead of joining a neighbouring branch.
    v_refusal := 'notice_not_reissuable';
  end if;

  -- ★ RESOLVABILITY IS CHECKED LAST, AND ONLY WHEN EVERYTHING ELSE PASSED, so an unreachable owner
  -- does not mask a more informative refusal. Fail closed: a row that cannot be sent must not be
  -- manufactured merely to satisfy a remediation workflow — it would settle failedPermanent on the
  -- next drain and leave the episode worse off, with a second dead generation and the evidence of the
  -- first one retired.
  if v_refusal is null and not v_resolvable then
    v_refusal := 'owner_channel_unreachable';
  end if;

  return jsonb_build_object(
    'eligible',                v_refusal is null,
    'refusal_code',            v_refusal,
    'case_is_current',         v_canonical is not null and v_canonical = p_case,
    'lifecycle_state',         v_state,
    'owner_channel_resolvable', v_resolvable,
    'prior_notice_id',         v_row.id,
    'prior_generation',        v_row.generation,
    'prior_status',            v_row.status,
    'prior_notice_kind',       v_row.notice_kind,
    'prior_failure_class',     v_row.failure_class,
    'prior_accepted',          v_row.id is not null and v_row.notice_accepted_at is not null,
    'next_generation',         case when v_refusal is null then v_row.generation + 1 end,
    'reissue_reason',          v_reason
  );
end $function$;
revoke execute on function public.owner_notice_reissue_assessment(uuid)
  from public, anon, authenticated;

comment on function public.owner_notice_reissue_assessment(uuid) is
  'The ONE decision about whether an episode may be re-noticed (Phase 11-OC / Phase C), consumed by '
  'both reissue_owner_safety_notice and the operator case-file projection so the console can never '
  'offer an action the door refuses. Every refusal carries a NAMED code from a closed set. Reports '
  'owner_channel_resolvable as a BOOLEAN and never an address. INTERNAL — its callers are gated; a '
  'client role cannot reach it.';

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- reissue_owner_safety_notice(p_case, p_reason) → jsonb                       [admin, AAL2+fresh]
-- ────────────────────────────────────────────────────────────────────────────────────────────────
--
-- ★ THE PARAMETER LIST IS THE SAFETY PROPERTY, AND WHAT IS ABSENT MATTERS MORE THAN WHAT IS PRESENT.
--
--   · NO RECIPIENT. The address is resolved inside this definer from `auth.users`, exactly as the
--     initial dispatch resolves it. Re-notice is not a recipient-edit feature, and a parameter here
--     would turn a remediation door into a way to mail an arbitrary address a message about somebody
--     else's estate.
--   · NO GENERATION. Computed under the predecessor's row lock, never supplied and never from an
--     unlocked `max()`.
--   · NO `reissue_reason` VOCABULARY VALUE. Derived from the predecessor's own status and
--     failure_class, so an operator cannot relabel an uncertain outcome as a definitive failure.
--   · NO ESTATE. The episode key is the CASE; taking an estate would invite the caller to name a
--     process, and the whole defect class here is a notice from one death process authorizing
--     another.
--   · NO STATUS, NO ACCEPTANCE TIMESTAMP. The new row starts `queued` with NULL acceptance and there
--     is no parameter through which either could be seeded.
--
-- `p_reason` is the operator's own free-text justification for the AUDIT. It is a different thing
-- from `reissue_reason` — one is why THIS PERSON acted, the other is what the PREDECESSOR's state
-- was — and conflating them is how a closed vocabulary becomes a text box.
--
-- ★ LOCK ORDER, WHICH IS THE CONCURRENCY CONTROL AND NOT A DETAIL.
--
--     1. the CASE row          — the episode identity, so two operators on one episode serialize
--     2. the CURRENT generation — so the generation number is computed under the row it increments
--
--   The winner supersedes and inserts. The loser blocks on (1); once the winner commits, every
--   subsequent statement in the loser's transaction takes a fresh snapshot, so it sees the NEW
--   current generation — `queued` — and refuses with `notice_still_queued`. Two generation-N+1 rows
--   are therefore unreachable, and the partial unique index
--   `owner_notice_outbox_one_current_per_episode_idx` is the wall behind that door: even with the
--   lock removed, a second row with `superseded_by is null` for the same episode is refused by the
--   database. Two layers, because a lock is a protocol and an index is a guarantee.
--
-- ★ THE PREDECESSOR IS RETIRED BEFORE THE SUCCESSOR EXISTS, AND THAT ORDER IS FORCED. Measured
-- against Postgres in migration 0058: with the self-FK immediate, insert-first raises
-- `unique_violation` (two rows momentarily satisfy `superseded_by is null`) and update-first raises
-- `foreign_key_violation` (the successor does not exist yet). The FK is DEFERRABLE INITIALLY
-- DEFERRED, so this routine pre-generates the successor's uuid, points the predecessor at it, then
-- inserts under that id. Integrity is unchanged — 0058 §5.3(g) proves a genuinely dangling pointer is
-- still refused at commit.
create or replace function public.reissue_owner_safety_notice(p_case uuid, p_reason text)
 returns jsonb
 language plpgsql
 security definer
 set search_path to 'public'
as $function$
declare
  v_uid        uuid;
  v_c          public.death_verification_cases%rowtype;
  v_prior      public.owner_notice_outbox%rowtype;
  v_verdict    jsonb;
  v_owner      uuid;
  v_recipient  text;
  v_new        uuid;
  v_gen        int;
  v_reason     text;
begin
  perform public.admin_require_gate();
  v_uid := auth.uid();

  -- ★ THE REASON IS REQUIRED AND CANNOT BE BLANK, and it is checked BEFORE anything is locked. "Fixing
  -- it" is not a reason; the audit row exists so somebody reconstructing a disputed release a year
  -- later can tell a legitimate remediation from an operator mailing a living person repeatedly.
  --
  -- ★ "CONTAINS NO NON-WHITESPACE CHARACTER" RATHER THAN `btrim(p_reason) = ''`, AND THE DIFFERENCE
  -- IS NOT PEDANTRY — it was found by execution. Single-argument `btrim` strips SPACES only, so a
  -- reason of one tab, or of a newline, passes that test and lands in the audit as a blank field.
  -- §11.9 sends `E'\t\n'` and the `btrim` form ACCEPTED it. The sibling routines in this schema
  -- (`purge_outbox_rows`, `authorize_release`) carry the narrower spelling; that is recorded as an
  -- observation in `docs/phase11oc-phase-c-owner-notice-reissue.md` rather than changed here, because
  -- widening a deployed reason check is its own decision and `authorize_release` is Phase D's file.
  if p_reason is null or p_reason !~ '[^[:space:]]' then
    raise exception 'reissue_reason_required' using errcode = 'P0001';
  end if;
  if p_case is null then
    raise exception 'case_not_found' using errcode = 'P0002';
  end if;

  -- LOCK 1 · the episode identity.
  select * into v_c from public.death_verification_cases c where c.id = p_case for update;
  if not found then
    raise exception 'case_not_found' using errcode = 'P0002';
  end if;

  -- LOCK 2 · the current generation, so `generation + 1` is computed under the row it increments.
  -- A missing row is legitimate here (the assessment names it `no_current_notice`), so this is not
  -- an assertion — it is a lock taken when there is something to lock.
  select * into v_prior
    from public.owner_notice_outbox o
   where o.case_id = p_case
     and o.channel = 'email'
     and o.notice_kind = any (public.owner_notice_episode_kinds())
     and o.superseded_by is null
   limit 1
   for update;

  -- ★ THE VERDICT COMES FROM THE SHARED ASSESSMENT, READ UNDER THE LOCKS ABOVE. The door does not
  -- restate the policy the console renders, so the two cannot disagree.
  v_verdict := public.owner_notice_reissue_assessment(p_case);
  if not (v_verdict ->> 'eligible')::boolean then
    raise exception '%', v_verdict ->> 'refusal_code' using errcode = 'P0001';
  end if;
  v_reason := v_verdict ->> 'reissue_reason';
  if v_reason is null then
    -- Unreachable: every eligible branch derives one, and the table CHECK pairs generation > 1 with a
    -- non-null reason. Asserted rather than trusted, because the alternative is an insert that fails
    -- on a constraint with no explanation of which branch forgot.
    raise exception 'reissue_reason_underived' using errcode = 'P0001';
  end if;

  -- ★ THE RECIPIENT IS DERIVED, THROUGH THE SAME AUTHORITATIVE PATH AS THE INITIAL DISPATCH:
  -- `estate_owner_user_id` → `auth.users.email`. Not `profiles.email` (user-editable in principle,
  -- and repointable by anyone who can write a profile) and not the predecessor row's stored value.
  --
  -- ★ THE RESIDUAL RISK IS REAL AND IS RECORDED RATHER THAN HIDDEN. Re-resolving means a re-notice
  -- goes to whatever address the account carries NOW. `lib/ownerNotices/drain.ts` deliberately does
  -- NOT re-resolve at SEND time, and that is the right rule there: a worker silently changing
  -- destination between enqueue and send is unaudited and unattended. This is different — an operator
  -- decides, a reason is required, and an audit row is written. Re-sending to the predecessor's stored
  -- address would also be inert for the commonest remediable failure there is, a hard bounce on a dead
  -- address. So the audit records WHETHER the resolved address differs from the predecessor's, as a
  -- BOOLEAN, never the address: an investigator gets the signal, and the audit gains no contact detail
  -- it would then carry forever.
  v_owner := public.estate_owner_user_id(v_c.estate_id);
  if v_owner is null then
    raise exception 'owner_unresolved' using errcode = 'P0001';
  end if;
  select u.email into v_recipient from auth.users u where u.id = v_owner;
  if v_recipient is null or btrim(v_recipient) = '' then
    -- Belt and braces with the assessment's `owner_channel_unreachable`: the assessment answers for
    -- the console, this answers for the write, and neither is allowed to depend on the other having
    -- run. A row with no destination would be claimed, fail, and settle failedPermanent — leaving the
    -- episode with a second dead generation and the first one retired.
    raise exception 'owner_channel_unreachable' using errcode = 'P0001';
  end if;

  v_gen := v_prior.generation + 1;
  v_new := gen_random_uuid();

  -- RETIRE the predecessor. This is the ONLY column of it this routine touches: every forensic field
  -- — requested_at, attempts, failure_class, dispatched_at, notice_accepted_at, case_id, generation,
  -- status, claimed_at — is left exactly as the drain left it.
  update public.owner_notice_outbox
     set superseded_by = v_new
   where id = v_prior.id;

  -- CREATE the successor. Every field that could carry a stale fact forward is written explicitly,
  -- rather than left to a default, so a reader can see that none of them is inherited:
  --   status             'queued'  — a new warning has been queued, nothing more
  --   notice_accepted_at NULL      — only the providerAccepted settle path may ever stamp it
  --   requested_at       now()     — the age gate must run from THIS request, not the predecessor's
  --   attempts           0         — the successor has its own retry budget
  --   claimed_at         NULL      — unclaimed
  --   dispatched_at      NULL      — nothing has been dispatched
  --   failure_class      NULL      — the predecessor's failure is on the predecessor
  --   next_attempt_at    NULL      — claimable by the next drain
  insert into public.owner_notice_outbox
    (id, estate_id, user_id, channel, recipient, notice_kind, status, requested_at, attempts,
     claimed_at, dispatched_at, failure_class, next_attempt_at, notice_accepted_at,
     case_id, generation, superseded_by, reissue_reason, reissued_by)
  values
    (v_new, v_c.estate_id, v_owner, 'email', v_recipient, public.owner_notice_reissue_kind(),
     'queued', now(), 0, null, null, null, null, null,
     p_case, v_gen, null, v_reason, v_uid);

  -- ★ THE AUDIT IS A DISTINCT ACTION, NEVER `owner_notice_dispatched`. That action means "an operator
  -- opened the window and started the challenge clock"; this one means "an operator queued an
  -- additional warning inside a window that was already open". Reusing the first would make the audit
  -- trail assert a lifecycle transition that did not happen, and would hide the reissue from anyone
  -- counting dispatches.
  --
  -- It names both generations and both row ids, so the supersession chain is reconstructible from the
  -- audit alone. It records the operator's reason and the derived vocabulary reason as separate
  -- fields. It records NO recipient address — the same discipline as the dispatch audit it follows.
  insert into public.audit_logs (actor_id, estate_id, action, target_table, target_id, metadata, source)
  values (v_uid, v_c.estate_id, 'death_process.owner_notice_reissued', 'owner_notice_outbox', v_new,
          jsonb_build_object(
            'severity',           'high',
            'case_id',            p_case,
            'prior_notice_id',    v_prior.id,
            'prior_generation',   v_prior.generation,
            'prior_status',       v_prior.status,
            'prior_failure_class', v_prior.failure_class,
            'prior_notice_kind',  v_prior.notice_kind,
            'new_notice_id',      v_new,
            'new_generation',     v_gen,
            'notice_kind',        public.owner_notice_reissue_kind(),
            'channel',            'email',
            'reissue_reason',     v_reason,
            'reason',             p_reason,
            -- A boolean, never the address. See the recipient note above.
            'recipient_changed',  v_recipient is distinct from v_prior.recipient),
          'admin');

  -- The return value is what an operator may know, and no more. No recipient, on any branch.
  return jsonb_build_object(
    'status',            'queued',
    'case_id',           p_case,
    'notice_id',         v_new,
    'generation',        v_gen,
    'notice_kind',       public.owner_notice_reissue_kind(),
    'notice_accepted_at', null,
    'reissue_reason',    v_reason,
    'prior_notice_id',   v_prior.id,
    'prior_generation',  v_prior.generation,
    'prior_status',      v_prior.status);
end $function$;
-- ★ THE GRANT IS THE DEFINER-DOOR DISCIPLINE, NOT A WIDENING. `authenticated` is the only role
-- PostgREST ever presents for a signed-in operator, so it is the role every admin door in this
-- repository is granted to — `authorize_release`, `dispatch_owner_safety_notice`, `purge_outbox_rows`
-- and both operator projections included. Authority comes from `admin_require_gate()` INSIDE the
-- definer (auth → is_admin → AAL2 → 15-minute freshness), so an owner, an executor, a claimant and
-- any other signed-in client hit the identical refusal a direct PostgREST caller would. `anon` is
-- revoked outright: an unauthenticated caller has no business reaching a safety-queue writer at all.
revoke execute on function public.reissue_owner_safety_notice(uuid, text) from public, anon;
grant  execute on function public.reissue_owner_safety_notice(uuid, text) to authenticated;

comment on function public.reissue_owner_safety_notice(uuid, text) is
  'Queues a NEW owner-safety notice generation for the CURRENT case episode (Phase 11-OC / Phase C). '
  'Eligible only when the current generation is failedPermanent, outcomeUncertain, or dispatched with '
  'NO acceptance fact (the pre-Phase-A legacy class) — and only from owner_notification_dispatched or '
  'challenge_window. Appends a row and retires the previous one with a pointer; mutates no forensic '
  'field of the predecessor. The new row starts queued with NULL acceptance, so a successful call '
  'means NEW WARNING QUEUED and never provider acceptance or delivery. Recipient is DERIVED, never '
  'supplied, and never returned. Requires a non-blank reason and writes '
  'death_process.owner_notice_reissued. Admin-gated inside the definer.';


-- ==== db/functions/outbox_safety.sql ==============================================================
-- ════════════════════════════════════════════════════════════════════════════════════════════════
-- PHASE 11-F · OUTBOX SAFETY — age gate, stale protection, and a purge that cannot be silent
-- ════════════════════════════════════════════════════════════════════════════════════════════════
--
-- ★ WHY A SAFETY NOTICE NEEDS DIFFERENT RULES FROM AN INVITATION EMAIL. `invitation_delivery_outbox`
-- is drained daily and its claim predicate has NO age bound: any `queued` row is claimable whenever
-- the worker next runs. For an invitation that is merely late. For the notice that tells a living
-- owner a process is running to release their estate, sending it three weeks after the fact is
-- worse than not sending it — the situation it describes has already resolved, and the message
-- would arrive as a false alarm about a window that closed, or a true alarm nobody can act on.
--
-- ★ SO STALENESS IS A DECISION, MADE ONCE, RECORDED. A notice older than the age gate is never
-- quietly sent and never quietly deleted: it is marked `failedPermanent` with an explicit failure
-- class, which leaves the evidence in place. Whether the estate should then still be releasable is
-- NOT this module's call — dispatch INITIATION already happened (Stage 2), and re-deciding that
-- here would be a second release authority hiding in a mail queue.
--
-- ★ AND NOTHING IS EVER SILENTLY DELETED (Stage 3). `purge_outbox_rows` writes an
-- `outbox_purge_audit` row BEFORE it deletes, in the same transaction, carrying the count and the
-- age range it removed. A purge with no audit row is impossible rather than discouraged.
--
-- Source of truth — re-apply on DB reset. Deploys with the release-authorization bundle.

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- owner_notice_age_gate() → interval                                                   [INTERNAL]
-- ────────────────────────────────────────────────────────────────────────────────────────────────
--
-- ★ DERIVED FROM THE CHALLENGE WINDOW, NOT CONFIGURED SEPARATELY. A notice is worth sending while
-- the window it announces could still matter; the window is 7 days (D2), so the gate is the window
-- plus one day of slack for a queue that fell behind. Two independently-tunable numbers would drift
-- apart, and the failure mode of that drift is a notice sent after its own window closed.
--
-- Fail-closed: an unconfigured window yields NULL, and a NULL gate makes `claim_owner_notices`
-- refuse to claim anything rather than treat everything as fresh.
create or replace function public.owner_notice_age_gate()
 returns interval
 language sql
 security definer
 stable
 set search_path to 'public'
as $function$
  select public.challenge_window_duration() + interval '1 day';
$function$;
revoke execute on function public.owner_notice_age_gate() from public, anon, authenticated;

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- owner_notice_claim_visibility() → interval                                          [INTERNAL]
-- ────────────────────────────────────────────────────────────────────────────────────────────────
--
-- ★ PHASE 11-OBR / OB-1. How long a claim is believed before the row is handed to another worker.
--
-- Derived from measured ceilings, not chosen for roundness: the provider request timeout is 10s
-- (`REQUEST_TIMEOUT_MS`), retried at most once on an ambiguous answer, so one row can legitimately
-- occupy a worker for ~20s; the drain runs on a serverless function whose execution ceiling is at
-- most 300s. One hour is therefore 12× the highest possible platform ceiling and ~180× the real
-- per-row cost — a row still `processing` an hour later is not slow, it is abandoned.
--
-- The upper bound matters as much: the stale sweep settles rows at `age_gate` (window + 1 day) and
-- the cron runs daily, so one hour leaves every one of those daily drains available as a recovery
-- opportunity instead of spending the gate waiting.
--
-- ★ IT IS A FUNCTION SO THERE IS EXACTLY ONE COPY. `claim_owner_notices` decides what to reclaim and
-- `owner_notice_census` reports how much is reclaimable; two literals would be two opinions about
-- the same bytes, and the first time they drifted the census would quietly stop describing what the
-- drain actually does. Not a policy table: the challenge window is a PRODUCT decision an operator
-- must be able to state, whereas this is an operational property of this worker whose only failure
-- mode is being set below the platform ceiling — which would reclaim rows out from under live
-- workers and manufacture the duplicate sends this module exists to avoid.
create or replace function public.owner_notice_claim_visibility()
 returns interval
 language sql
 immutable
 set search_path to 'public'
as $function$
  select interval '1 hour';
$function$;
revoke execute on function public.owner_notice_claim_visibility() from public, anon, authenticated;

comment on function public.owner_notice_claim_visibility() is
  'How long an owner-notice claim is believed before the row may be reclaimed (Phase 11-OBR). One '
  'hour: 12x the highest serverless execution ceiling and ~180x the real per-row send cost, and far '
  'inside the age gate so every daily drain remains a recovery opportunity. Single-sourced so the '
  'claim routine and the census cannot disagree about what is stale.';

comment on function public.owner_notice_age_gate() is
  'How old an owner safety notice may be and still be worth sending (Phase 11-F): the challenge '
  'window plus one day of queue slack, DERIVED so the two cannot drift apart. NULL when the window '
  'is unconfigured, which makes the claim routine refuse rather than treat everything as fresh.';

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- claim_owner_notices(p_max) → setof                                                   [INTERNAL]
-- ────────────────────────────────────────────────────────────────────────────────────────────────
--
-- The claim side of the owner-notice channel, with the age gate applied BEFORE anything is handed
-- to a sender. Two populations leave the queue on every call:
--
--   · STALE  — older than the gate. Marked `failedPermanent`, class `stale_beyond_age_gate`. Never
--              sent, never deleted. The row is the evidence that the owner was not reached in time,
--              which an operator investigating a disputed release will want.
--   · FRESH  — claimed for delivery with `for update skip locked`, so two concurrent drains never
--              hand the same notice out twice.
--
-- ★ PHASE 11-K WIRED THE CRON. 11-F's note read: "NO CRON IS WIRED TO THIS IN 11-F, DELIBERATELY.
-- Enabling a new delivery path is a deployment decision with its own operator step, and the phase
-- brief's own instruction is to build the safety BEFORE enabling the path. The routine exists, is
-- tested, and waits." The safety was built; 11-K enables the path. The drain is
-- `lib/ownerNotices/drain.ts`, reached by `GET /api/claims/drain_outboxes` under CRON_SECRET, and it
-- claims through this routine as `service_role` — the grant is at the foot of this section.
--
-- ★ THE ROUTE NAME IS NOT `drain_owner_notices`, AND THIS COMMENT USED TO SAY IT WAS. There is no
-- such endpoint: it returns 404 in production, verified by probing it. `drain_owner_notices` is only
-- the LOG LABEL for the owner-notice half inside the shared dispatcher. The half shares the claims
-- cron slot because Vercel Hobby permits exactly two cron jobs, so it could never have its own path.
-- A comment naming a 404 is not cosmetic in THIS module: §5/§7 of the deployment doc verify the
-- channel by probing it, and an engineer who probes the name written here gets a 404 and concludes
-- the drain was never deployed — a false negative about the only independent channel that warns a
-- living owner their estate is being released.
create or replace function public.claim_owner_notices(p_max int default 25)
 returns table (id uuid, estate_id uuid, recipient text, notice_kind text)
 language plpgsql
 security definer
 set search_path to 'public'
as $function$
declare
  v_gate interval;
  v_max  int;
  -- ★ PHASE 11-OBR / OB-1 — the claim visibility timeout, read from the ONE place that defines it
  -- (`owner_notice_claim_visibility()`), so this routine and `owner_notice_census` can never
  -- disagree about which rows are stale.
  v_visibility interval := public.owner_notice_claim_visibility();
begin
  v_gate := public.owner_notice_age_gate();
  if v_gate is null then
    -- Fail-closed: with no configured window there is no defensible notion of "too old", so the
    -- queue is not drained at all rather than drained by a guess.
    raise exception 'owner_notice_age_gate_unconfigured' using errcode = 'P0001';
  end if;
  v_max := least(greatest(coalesce(p_max, 25), 1), 100);

  -- STALE FIRST, so a stale row can never be claimed for sending by the same call.
  update public.owner_notice_outbox o
     set status = 'failedPermanent',
         failure_class = 'stale_beyond_age_gate',
         next_attempt_at = null
   where o.status in ('queued', 'processing')
     and o.requested_at < now() - v_gate;

  -- ────────────────────────────────────────────────────────────────────────────────────────────
  -- ★ THE CLAIM SET IS CLOSED AND WRITTEN OUT AS TWO NAMED BRANCHES (OB-1).
  -- ────────────────────────────────────────────────────────────────────────────────────────────
  --
  --   A · queued           — claimable immediately, subject to its backoff. Unchanged.
  --   B · processing, stale — claimed by a worker that never settled it. Reclaimable ONLY once the
  --                           claim is older than the visibility timeout.
  --
  -- Every other status is excluded, and excluded BY NAME rather than by falling through a
  -- `status <> terminal` predicate. `dispatched`, `outcomeUncertain`, `failedPermanent` and
  -- `cancelled` are all settled: two of them are terminal precisely because the message may already
  -- be in the owner's inbox, and a broad "not terminal" test is exactly how a future status added to
  -- the CHECK constraint would silently become re-sendable.
  --
  -- ★ `claimed_at IS NULL` ON A `processing` ROW IS RECLAIMABLE, AND THAT IS A DECISION.
  -- Such a row was claimed before `claimed_at` existed (migration 0057), which means it has been
  -- sitting in `processing` since at least the deployment — already far beyond any timeout. Treating
  -- NULL as "infinitely stale" is what lets the DEPLOYED mechanism recover the rows the defect
  -- already stranded, rather than requiring a hand-written repair for each one. It is a class rule;
  -- no row is named.
  --
  -- ★ WHAT A RECLAIM COSTS, STATED HONESTLY. A reclaimed row is re-sent under the SAME deterministic
  -- `Idempotency-Key` (`afterworth/owner-notice/<row id>`, built in `lib/ownerNotices/drain.ts` from
  -- the row id with no generation counter), so the provider is asked to no-op a repeat. That is the
  -- same operation the worker ALREADY performs when it retries an ambiguous first attempt — this
  -- does not re-mint a message, it replays one. It is nevertheless AT-LEAST-ONCE, not exactly-once:
  -- the provider's dedupe retention is a vendor property this repository does not pin, and a reclaim
  -- that lands outside it could produce a second copy. See docs/phase11ob-owner-notice-delivery-defect.md.
  return query
  with candidate as (
    select o.id
      from public.owner_notice_outbox o
     where o.requested_at >= now() - v_gate
       and (
         -- A · the ordinary queue
         (o.status = 'queued'
          and (o.next_attempt_at is null or o.next_attempt_at <= now()))
         -- B · an abandoned claim
         or (o.status = 'processing'
             and (o.claimed_at is null or o.claimed_at < now() - v_visibility))
       )
     order by o.requested_at
     limit v_max
     for update skip locked
  )
  update public.owner_notice_outbox o
     set status     = 'processing',
         attempts   = o.attempts + 1,
         -- Stamped on EVERY claim, first or repeat: the timeout must run from THIS claim, or a
         -- reclaimed row would be instantly reclaimable again by the next concurrent drain.
         claimed_at = now()
    from candidate c
   where o.id = c.id
  returning o.id, o.estate_id, o.recipient, o.notice_kind;
end $function$;
-- ★ THE WORKER GRANT (11-K), AND WHY IT IS NOT `authenticated`. Claiming is a WORKER act, not an
-- operator act: it moves a live safety message into `processing` and hands it to a sender. An
-- operator who could claim could also strand a notice in `processing`, where the stale sweep will
-- eventually mark it failedPermanent — an owner silently un-notified by a console click. The 0043
-- precedent exactly: the claim/record pair is service_role only, revoked from every client role.
revoke execute on function public.claim_owner_notices(int) from public, anon, authenticated;
grant  execute on function public.claim_owner_notices(int) to service_role;

comment on function public.claim_owner_notices(int) is
  'Claims owner safety notices for delivery, applying the age gate FIRST (Phase 11-F, Stage 3): '
  'rows older than the gate are marked failedPermanent/stale_beyond_age_gate and are never sent and '
  'never deleted. Fresh rows are claimed with skip-locked so concurrent drains cannot double-send. '
  'Refuses entirely when the age gate is unconfigured. service_role ONLY (Phase 11-K wired the '
  'drain); no client role may claim.';

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- record_owner_notice_outcome(p_id, p_outcome, p_failure_class) → text            [service_role]
-- ────────────────────────────────────────────────────────────────────────────────────────────────
--
-- ★ THE HALF 11-F LEFT OUT, AND THE REASON A DRAIN COULD NOT BE WRITTEN UNTIL NOW.
-- `claim_owner_notices` moves a row to `processing` and returns it. Nothing wrote back what the
-- sender then learned — so any worker built on the 11-F schema would have claimed rows and stranded
-- every one of them in `processing`, where the stale sweep would later mark them failedPermanent.
-- The queue would have looked drained and no owner would have been reached.
--
-- Modelled on `record_invitation_delivery_outcome` (0043) with three deliberate differences, each
-- forced by what THIS channel is for:
--
--   · NO GENERATION GUARD, because there is no generation column and no reissue concept. A safety
--     notice is dispatched once, by one transition, and is never re-minted. What replaces the guard
--     is the settled-status check below: a row that has already settled is a no-op.
--
--   · NO PROVIDER MESSAGE ID IS STORED. The table has no column for one and gains none. A provider
--     handle is a lookup key into a third party's log of a message addressed to a living owner; the
--     operational fact this product needs is the outcome, and that is what is recorded.
--
--   · A LOWER CAP AND A SHORTER BACKOFF. Invitations retry 5 times with up to 12h between attempts,
--     which is right for a message that is merely late. This notice is only worth sending inside
--     the age gate (window + 1 day), so a 12h backoff would spend the whole gate on two attempts.
--     Three attempts at ~1h/2h/3h all land comfortably inside it.
--
-- ★ ACCEPTED AND UNCERTAIN ARE BOTH TERMINAL, for the same reason: the message may already be in
-- the owner's inbox, and this product will not send a second copy of a notice about their own death
-- on the strength of a lost HTTP response. Only `retryPending` — where the provider ANSWERED and
-- refused, proving nothing was accepted — returns a row to `queued`.
create or replace function public.record_owner_notice_outcome(
  p_id            uuid,
  p_outcome       text,
  p_failure_class text default null
)
 returns text
 language plpgsql
 security definer
 set search_path to 'public'
as $function$
declare
  v_row    public.owner_notice_outbox%rowtype;
  v_status text;
  v_next   timestamptz;
  v_class  text;
  c_max_attempts constant int := 3;
begin
  if p_outcome not in ('providerAccepted', 'outcomeUncertain', 'retryPending', 'failedPermanent') then
    raise exception 'invalid_outcome' using errcode = 'P0001';
  end if;

  select * into v_row from public.owner_notice_outbox where id = p_id for update;
  if not found then
    raise exception 'outbox_entry_not_found' using errcode = 'P0002';
  end if;

  -- Already settled: report current state, change nothing, write no second audit row. Covers a
  -- duplicate callback and an operator-cancelled row alike.
  if v_row.status in ('dispatched', 'outcomeUncertain', 'failedPermanent', 'cancelled') then
    return v_row.status;
  end if;

  v_class := case when p_outcome in ('retryPending', 'failedPermanent') then p_failure_class else null end;
  v_next  := null;

  if p_outcome = 'providerAccepted' then
    v_status := 'dispatched';
  elsif p_outcome = 'outcomeUncertain' then
    v_status := 'outcomeUncertain';
  elsif p_outcome = 'failedPermanent' then
    v_status := 'failedPermanent';
  else
    if v_row.attempts >= c_max_attempts then
      v_status := 'failedPermanent';
      v_class  := coalesce(v_class, 'retry_cap_exhausted');
    else
      v_status := 'queued';
      v_next   := now() + make_interval(hours => least(greatest(v_row.attempts, 1), 3));
    end if;
  end if;

  -- ★ PHASE 11-OC — ACCEPTANCE IS STAMPED IN THIS ONE STATEMENT, BESIDE THE STATUS IT AGREES WITH.
  --
  -- `notice_accepted_at` is the fact Phase D makes release-authoritative, and it is written here and
  -- nowhere else. One UPDATE, so `dispatched` + NULL acceptance is structurally unreachable for any
  -- row written after Phase A — which is what lets the re-notice routine treat that combination as
  -- an unambiguous LEGACY marker rather than as a state it might have produced itself.
  --
  -- ★ IT IS KEYED ON `p_outcome`, NOT ON `v_status`. They agree today: `providerAccepted` is the only
  -- branch that yields `dispatched`. Keying on the OUTCOME ties the stamp to what the provider
  -- actually reported, so if a future branch ever reaches `dispatched` by another route it does not
  -- silently inherit an acceptance fact nobody established. `outcomeUncertain`, `retryPending` and
  -- `failedPermanent` all leave it NULL — an unknown outcome must never be recorded as an acceptance,
  -- which is the whole reason this column exists rather than a status list.
  --
  -- First-write-wins needs no `where notice_accepted_at is null` guard: the settled-status no-op
  -- above already makes a second settle unreachable, and a redundant guard here would mask a future
  -- change to that no-op instead of failing beside it.
  update public.owner_notice_outbox
     set status             = v_status,
         failure_class      = v_class,
         next_attempt_at    = v_next,
         dispatched_at      = case when v_status = 'dispatched' then now() else dispatched_at end,
         notice_accepted_at = case when p_outcome = 'providerAccepted' then now()
                                   else notice_accepted_at end
   where id = p_id;

  -- ★ THE AUDIT NAMES THE OUTCOME AND THE CHANNEL CLASS, NEVER THE ADDRESS — the same discipline as
  -- the dispatch audit it follows. An audit row outlives every reason anyone had to read it.
  -- actor_id is NULL because the actor is a scheduled worker, not a person; `source = 'worker'`
  -- says so without inventing a synthetic operator identity.
  insert into public.audit_logs (actor_id, estate_id, action, target_table, target_id, metadata, source)
  values (null, v_row.estate_id, 'death_process.owner_notice_outcome', 'owner_notice_outbox', p_id,
          jsonb_build_object('severity', 'high', 'outcome', v_status,
                            'failure_class', v_class, 'attempts', v_row.attempts,
                            'channel', v_row.channel, 'notice_kind', v_row.notice_kind),
          'worker');
  return v_status;
end $function$;
revoke execute on function public.record_owner_notice_outcome(uuid, text, text)
  from public, anon, authenticated;
grant  execute on function public.record_owner_notice_outcome(uuid, text, text) to service_role;

comment on function public.record_owner_notice_outcome(uuid, text, text) is
  'Write-back half of the owner-safety notice drain (Phase 11-K). providerAccepted -> dispatched; '
  'retryPending -> queued with backoff until a 3-attempt cap, then failedPermanent; '
  'outcomeUncertain and failedPermanent are terminal. An already-settled row is a no-op, so a '
  'duplicate callback can never produce a second send. Records no recipient address. service_role only.';

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- purge_outbox_rows(p_outbox, p_before, p_reason) → int                       [admin, AAL2+fresh]
-- ────────────────────────────────────────────────────────────────────────────────────────────────
--
-- ★ THE AUDIT ROW IS WRITTEN BEFORE THE DELETE, IN THE SAME TRANSACTION. Not after — an audit
-- written afterwards is an audit that a failure can skip, leaving rows gone and no record of who
-- removed them or why. Here the audit and the deletion commit together or neither happens.
--
-- ★ A REASON IS REQUIRED AND CANNOT BE BLANK. "Cleaning up" is not a reason; the column exists so
-- that someone reconstructing a disputed release a year later can tell a routine hygiene sweep from
-- a deletion that removed the evidence of an owner who was never reached.
--
-- ★ IT REFUSES TO TOUCH ROWS THAT ARE STILL ACTIONABLE. `queued` and `processing` notices are live
-- safety messages; purging those would be deleting an owner's warning while it is still in flight.
-- Only settled rows (dispatched / failedPermanent / cancelled) can be purged, and only ones older
-- than an explicit cutoff the caller states.
create or replace function public.purge_outbox_rows(
  p_outbox text,
  p_before timestamptz,
  p_reason text
)
 returns int
 language plpgsql
 security definer
 set search_path to 'public'
as $function$
declare
  v_uid    uuid;
  v_count  int;
  v_oldest timestamptz;
  v_newest timestamptz;
  v_audit  uuid;
begin
  perform public.admin_require_gate();
  v_uid := auth.uid();

  if p_reason is null or btrim(p_reason) = '' then
    raise exception 'purge_reason_required' using errcode = 'P0001';
  end if;
  if p_before is null then
    raise exception 'purge_cutoff_required' using errcode = 'P0001';
  end if;
  -- A closed vocabulary of purgeable outboxes. An unknown name is refused rather than resolved
  -- dynamically: `execute format('delete from %I')` on a caller-supplied table is how an admin
  -- routine becomes a general-purpose delete.
  if p_outbox is distinct from 'owner_notice_outbox' then
    raise exception 'unknown_outbox' using errcode = 'P0001';
  end if;

  select count(*), min(requested_at), max(requested_at)
    into v_count, v_oldest, v_newest
    from public.owner_notice_outbox
   where status in ('dispatched', 'failedPermanent', 'cancelled')
     and requested_at < p_before;

  if v_count = 0 then
    return 0; -- nothing to purge writes no audit row: an audit of a no-op is noise, not evidence
  end if;

  insert into public.outbox_purge_audit
    (outbox_name, actor_id, row_count, oldest_row_at, newest_row_at, reason)
  values (p_outbox, v_uid, v_count, v_oldest, v_newest, p_reason)
  returning id into v_audit;

  -- Stamp the audit id onto the rows first, so even a partial failure leaves the link.
  update public.owner_notice_outbox
     set purge_audit_id = v_audit
   where status in ('dispatched', 'failedPermanent', 'cancelled')
     and requested_at < p_before;

  delete from public.owner_notice_outbox
   where status in ('dispatched', 'failedPermanent', 'cancelled')
     and requested_at < p_before;

  insert into public.audit_logs (actor_id, estate_id, action, target_table, target_id, metadata, source)
  values (v_uid, null, 'outbox.purged', 'outbox_purge_audit', v_audit,
          jsonb_build_object('severity', 'high', 'outbox', p_outbox, 'row_count', v_count,
                            'oldest_row_at', v_oldest, 'newest_row_at', v_newest,
                            'reason', p_reason),
          'admin');
  return v_count;
end $function$;
revoke execute on function public.purge_outbox_rows(text, timestamptz, text) from public, anon;
grant  execute on function public.purge_outbox_rows(text, timestamptz, text) to authenticated;

comment on function public.purge_outbox_rows(text, timestamptz, text) is
  'Purges SETTLED owner-notice rows older than an explicit cutoff (Phase 11-F, Stage 3). Writes the '
  'outbox_purge_audit row BEFORE deleting, in the same transaction, so a silent purge is impossible. '
  'Requires a non-blank reason, refuses an unknown outbox name, and never touches queued or '
  'processing rows — those are live safety messages still in flight.';

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- owner_notice_census() → jsonb                                                [admin, AAL2+fresh]
-- ────────────────────────────────────────────────────────────────────────────────────────────────
--
-- The read-only classification Stage 3 requires before any delivery path is enabled: totals, status
-- distribution, age distribution, and the actionable/stale split — computed against the CURRENT age
-- gate rather than against a remembered one. Counts only; no recipient address, no estate name.
create or replace function public.owner_notice_census()
 returns jsonb
 language plpgsql
 security definer
 stable
 set search_path to 'public'
as $function$
declare v_gate interval; v_out jsonb;
begin
  perform public.admin_require_gate();
  v_gate := public.owner_notice_age_gate();

  -- ★ TWO SEPARATE AGGREGATIONS, COMBINED — NOT A LATERAL JOIN. The first draft joined a
  -- per-status GROUP BY laterally onto the row set, which returns every status group for EVERY row:
  -- three rows across three statuses became nine, and `total` reported 9. The status map looked
  -- right (duplicate keys resolve last-wins), so a test asserting only the presence of keys passed
  -- while the headline number was triple the truth. A census whose total is wrong is worse than no
  -- census — it is the number an operator would quote when deciding whether to purge.
  with rows as (
    select o.status, o.requested_at, o.claimed_at,
           -- ★ PHASE 11-OC. The three facts that make the Phase D blast radius countable.
           o.notice_accepted_at, o.case_id, o.superseded_by, o.generation
      from public.owner_notice_outbox o
  ),
  by_gen as (
    select coalesce(jsonb_object_agg(t.generation::text, t.n), '{}'::jsonb) as m
      from (select r.generation, count(*) as n from rows r group by r.generation) t
  ),
  by_status as (
    select coalesce(jsonb_object_agg(t.status, t.n), '{}'::jsonb) as m
      from (select r.status, count(*) as n from rows r group by r.status) t
  )
  select jsonb_build_object(
    'total', (select count(*) from rows),
    'by_status', (select m from by_status),
    'age_gate', v_gate::text,
    'oldest_requested_at', (select min(r.requested_at) from rows r),
    'newest_requested_at', (select max(r.requested_at) from rows r),
    'actionable', (select count(*) from rows r
                    where r.status = 'queued'
                      and v_gate is not null and r.requested_at >= now() - v_gate),
    'stale', (select count(*) from rows r
               where r.status in ('queued', 'processing')
                 and v_gate is not null and r.requested_at < now() - v_gate),
    -- ★ 11-K: without this key an `outcomeUncertain` row would appear in `total` and `by_status`
    -- and in NONE of the three splits, so an operator reconciling actionable+stale+purgeable
    -- against the total would find a gap with no name — and a nameless gap in a safety queue is
    -- the number someone eventually explains away. It is counted separately rather than folded
    -- into `purgeable` because it is deliberately NOT purgeable.
    'uncertain', (select count(*) from rows r where r.status = 'outcomeUncertain'),
    'purgeable', (select count(*) from rows r
                   where r.status in ('dispatched', 'failedPermanent', 'cancelled')),
    -- ★ PHASE 11-OBR / OB-1 — THE STUCK-CLAIM SPLIT, WITHOUT WHICH THIS DEFECT IS INVISIBLE.
    --
    -- The Branch A notice sat at `processing` for a day and nothing anywhere said so: `by_status`
    -- carried a `processing: 1` that reads as healthy in-flight work, and there was no way to ask
    -- how long it had been in flight. These three keys are what turn "a notice is being sent" into
    -- "a notice has been abandoned", which is a different operational fact entirely.
    --
    -- `processing_stale` uses the SAME predicate the drain reclaims by — including its NULL branch —
    -- read from `owner_notice_claim_visibility()` rather than restated, so this number is exactly
    -- "rows the next drain will pick up" and not an approximation of it.
    'processing_total', (select count(*) from rows r where r.status = 'processing'),
    'processing_stale', (select count(*) from rows r
                          where r.status = 'processing'
                            and (r.claimed_at is null
                                 or r.claimed_at < now() - public.owner_notice_claim_visibility())),
    -- Age of the OLDEST claim still in flight, as an interval string. NULL when nothing is
    -- processing. A legacy row with no claimed_at cannot have an age computed, so it reports NULL
    -- here and is counted in `processing_stale` above — the count is the alarm, this is the detail.
    'oldest_processing_age', (select (now() - min(r.claimed_at))::text from rows r
                               where r.status = 'processing' and r.claimed_at is not null),
    -- ────────────────────────────────────────────────────────────────────────────────────────
    -- ★ PHASE 11-OC — THE ACCEPTANCE AND EPISODE SPLITS.
    -- ────────────────────────────────────────────────────────────────────────────────────────
    --
    -- These four keys are what make the Phase D blast radius a NUMBER instead of an argument. They
    -- follow the `uncertain` key's discipline exactly: every row must land in a NAMED split, because
    -- a nameless gap in a safety queue is the number someone eventually explains away.
    --
    -- The reconciliation an operator can perform, and which the suite asserts:
    --
    --   accepted_total + unaccepted_total            = total
    --   legacy_unaccepted ⊆ unaccepted_total         (it is the `dispatched` slice of it)
    --   sum(by_generation values)                    = total
    --
    -- `accepted_total` counts the FACT, not the status: a row is accepted because a provider
    -- acceptance was stamped on it, never because it reached some status.
    'accepted_total',   (select count(*) from rows r where r.notice_accepted_at is not null),
    'unaccepted_total', (select count(*) from rows r where r.notice_accepted_at is null),
    -- ★ THE LEGACY POPULATION, PRECISELY. `dispatched` with no acceptance fact is the shape that
    -- existed before Phase A and is structurally unreachable after it (status and acceptance are
    -- written in one UPDATE). A non-zero count here is therefore a count of PRE-PHASE-A rows, which
    -- is exactly the population Phase D would refuse and Phase C must remediate.
    'legacy_unaccepted', (select count(*) from rows r
                           where r.status = 'dispatched' and r.notice_accepted_at is null),
    -- Rows that belong to no episode. Also strictly pre-Phase-A: the INSERT trigger refuses a NULL
    -- case_id, so this can only shrink.
    'no_episode',       (select count(*) from rows r where r.case_id is null),
    'superseded_total', (select count(*) from rows r where r.superseded_by is not null),
    'current_total',    (select count(*) from rows r where r.superseded_by is null),
    'by_generation',    (select m from by_gen)
  ) into v_out;

  return v_out;
end $function$;
revoke execute on function public.owner_notice_census() from public, anon;
grant  execute on function public.owner_notice_census() to authenticated;

comment on function public.owner_notice_census() is
  'Read-only owner-notice outbox classification (Phase 11-F, Stage 3): totals, status and age '
  'distribution, and the actionable/stale/purgeable split against the CURRENT age gate. Phase 11-OC '
  'adds the acceptance and episode splits (accepted_total, legacy_unaccepted, no_episode, '
  'superseded_total, by_generation), each reconciling against total with no nameless gap. Counts '
  'only — never a recipient address. Admin-gated.';

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- owner_notice_release_readiness_census() → jsonb                            [admin, AAL2+fresh]
-- ────────────────────────────────────────────────────────────────────────────────────────────────
--
-- ★ PHASE 11-OC · THE BLAST RADIUS, AS A NUMBER, BEFORE THE POLICY THAT CREATES IT.
--
-- `owner_notice_census` counts ROWS. This counts ESTATES AT THE DOOR — the population Phase D's
-- stricter release predicate will actually judge — classified by the state of the CURRENT generation
-- of the CURRENT case episode. It exists so the Phase D cutover decision is made against a measured
-- count rather than an assumption, and so the class that needs the Phase C remedy is named before it
-- is blocked.
--
-- ★ IT IS SCOPED EXACTLY AS THE PHASE D PREDICATE WILL BE, OR IT WOULD BE MEASURING SOMETHING ELSE.
-- Current case episode (`status = 'verified'`, newest `decided_at`), current generation
-- (`superseded_by is null`), email channel, window-opened kind. A census that aggregated by estate
-- would count an accepted notice from a prior REJECTED case as readiness for a new one — which is
-- the exact defect Phase D exists to close, reproduced in the instrument built to measure it.
--
-- ★ EVERY ESTATE LANDS IN EXACTLY ONE NAMED BUCKET, AND THE BUCKETS RECONCILE AGAINST THE TOTAL.
-- The `uncertain` discipline again: a nameless remainder is the number someone explains away. The
-- suite asserts the sum, so a future status that fell through would break the reconciliation rather
-- than hide in it.
--
-- ★ TWO ABSENCES ARE DISTINGUISHED, BECAUSE THE OPERATOR'S NEXT ACTION DIFFERS.
--   · `no_current_notice`            — no notice row names this case at all. Needs dispatch, not
--                                      re-notice. Fail-closed either way.
--   · `ambiguous_historical_linkage` — the estate HAS notice rows but they carry a NULL case_id, so
--                                      which episode they belong to is unprovable. These are
--                                      pre-Phase-A rows and are NEVER guessed into an episode; the
--                                      remedy is a re-notice that produces a fact, never a backfill
--                                      that invents one.
--
-- ★ PRIVACY-MINIMIZED BY CONSTRUCTION. Counts only. No estate id, no estate name, no case id, no
-- user id, no recipient address — on any branch. There is nothing here to correlate back to a living
-- owner, which is the point: an operator deciding a rollout needs a distribution, not a roster.
create or replace function public.owner_notice_release_readiness_census()
 returns jsonb
 language plpgsql
 security definer
 stable
 set search_path to 'public'
as $function$
declare v_out jsonb;
begin
  perform public.admin_require_gate();

  with door as (
    -- Every estate standing at the release door. `challenge_window` is the ONLY state Phase D's
    -- predicate governs; a released estate is past the door and an earlier one has not reached it.
    --
    -- ★ THE TABLE, NOT `estate_lifecycle_state()`, AND THE CHOICE IS FORCED RATHER THAN CASUAL.
    --
    -- `deathVerificationFoundation.test.ts` keeps two lists with two different privileges, and this
    -- read had to land in one of them. Going through the reader looks stricter and violates the OTHER
    -- rule in the same audit: outside the death module the reader may appear only as an argument to
    -- `release_condition_satisfied`, never in a local comparison — because
    -- `if estate_lifecycle_state(e) = '…'` is release policy leaking back out of the canonical module
    -- one `if` at a time, which that audit calls the single most likely accident here. A
    -- `where estate_lifecycle_state(e.id) = 'challenge_window'` scan is exactly that shape.
    --
    -- So this file joins `LIFECYCLE_TABLE_READERS`, the list `operator_console.sql` already occupies
    -- for the same reason: an operator PROJECTION that reports where the machine stands. Membership
    -- carries a proof obligation the other lists do not — the audit asserts every member is READ-ONLY
    -- against the lifecycle — and this file satisfies it: the census is `stable`, selects only, and
    -- names no transition, no lifecycle UPDATE and no INSERT.
    select l.estate_id
      from public.estate_lifecycle l
     where l.state = 'challenge_window'
  ),
  cur_case as (
    -- The CURRENT episode key, resolved exactly as authorize_release resolves it.
    select d.estate_id,
           (select c.id from public.death_verification_cases c
             where c.estate_id = d.estate_id and c.status = 'verified'
             order by c.decided_at desc limit 1) as case_id
      from door d
  ),
  cur_gen as (
    select cc.estate_id,
           cc.case_id,
           o.status,
           -- ★ ACCEPTANCE IS AN EXISTENTIAL OVER THE WHOLE EPISODE, NEVER A PROPERTY OF THE CURRENT
           -- GENERATION — and this census got that wrong on its first draft, which its own direction-1
           -- positive control caught.
           --
           -- The door asks "did ANY generation of this episode reach provider acceptance?". Reading
           -- only the current generation implements "latest generation only", which the architecture
           -- rejects explicitly: an already-accepted generation 1 would STOP qualifying the moment a
           -- generation 2 was created, so issuing a notice would REMOVE release authority and hand an
           -- operator a lever that suppresses a release. Authority is monotone — creating a generation
           -- can only ever ADD it — which is the same property that makes the MIN anchor immutable.
           --
           -- This must match the Phase D predicate exactly, or the console and the door disagree about
           -- the same estate.
           --
           -- ★ PHASE C — THE EPISODE IS A KIND SET, NOT ONE LITERAL, AND THAT IS WHAT MAKES THE
           -- REMEDY VISIBLE TO THE INSTRUMENT THAT MEASURES IT. A deliberate re-notice takes
           -- `death_process.window_renotice` (migration 0059) so a second warning is never recorded
           -- as the initial window-opening event. Left as the Phase A literal, this predicate could
           -- not see a re-notice at all: a remediated estate would keep reporting as REFUSED however
           -- many times it was re-noticed, its eventual provider acceptance would never be counted,
           -- and Phase C would be inert in exactly the census built to prove Phase C works.
           --
           -- Read from `owner_notice_episode_kinds()` rather than restated, for the reason
           -- `owner_notice_claim_visibility()` gives: two literals are two opinions about the same
           -- bytes, and the door and the census must never hold different ones.
           exists (
             select 1 from public.owner_notice_outbox a
              where a.case_id = cc.case_id
                and a.channel = 'email'
                and a.notice_kind = any (public.owner_notice_episode_kinds())
                and a.notice_accepted_at is not null
           ) as accepted_any,
           -- Does the estate carry any unlinkable pre-Phase-A row? Only consulted when no current
           -- generation was found, to separate "never dispatched" from "cannot be proven".
           (select count(*) from public.owner_notice_outbox z
             where z.estate_id = cc.estate_id and z.case_id is null) as orphan_rows
      from cur_case cc
      -- Phase C: the CURRENT generation may be a re-notice, so the join reads the episode kind SET
      -- for the same reason `accepted_any` above does. Left as one literal, a remediated estate would
      -- report `no_current_notice` — an estate that has just been re-noticed described as one that
      -- was never dispatched, which is the opposite of the truth and would send an operator to
      -- dispatch a window that is already open.
      left join public.owner_notice_outbox o
        on o.case_id = cc.case_id
       and o.channel = 'email'
       and o.notice_kind = any (public.owner_notice_episode_kinds())
       and o.superseded_by is null
  ),
  classified as (
    select case
             when case_id is null                              then 'no_verified_case'
             -- ★ THE ACCEPTANCE TEST COMES FIRST, and it is the ONLY bucket that decides admission.
             -- Everything below it describes what the CURRENT generation is doing, which is
             -- diagnostic information for an operator — useful, and not the release question.
             when accepted_any                                 then 'accepted'
             when status is null and orphan_rows > 0           then 'ambiguous_historical_linkage'
             when status is null                               then 'no_current_notice'
             when status = 'dispatched'                        then 'legacy_dispatched_unaccepted'
             when status = 'outcomeUncertain'                  then 'outcome_uncertain'
             when status = 'failedPermanent'                   then 'failed_permanent'
             when status = 'queued'                            then 'queued'
             when status = 'processing'                        then 'processing'
             when status = 'cancelled'                         then 'cancelled'
             -- ★ NOT A FALL-THROUGH. A status outside the six lands HERE, by name, so a widened
             -- CHECK constraint shows up as an unclassified count instead of silently joining a
             -- neighbouring bucket. The reconciliation assertion in the suite then fails loudly.
             else 'unclassified'
           end as bucket
      from cur_gen
  )
  select jsonb_build_object(
    'estates_at_door', (select count(*) from classified),
    'by_readiness',    coalesce((select jsonb_object_agg(t.bucket, t.n)
                                   from (select bucket, count(*) as n from classified group by bucket) t),
                                '{}'::jsonb),
    -- ★ THE ONE NUMBER THE PHASE D GATE TURNS ON. Estates at the door whose current episode carries
    -- NO provable provider acceptance — i.e. exactly those Phase D would refuse with
    -- `notice_never_accepted`. If this is non-zero, Phase D must not activate for that class until
    -- the Phase C re-notice remedy is deployed and operational.
    'would_be_refused_by_phase_d',
      (select count(*) from classified where bucket <> 'accepted'),
    'would_be_admitted_by_phase_d',
      (select count(*) from classified where bucket = 'accepted'),
    -- Retained so a reader can see that the strict policy is strictly narrower than today's, without
    -- having to reason about it: today's predicate admits every estate with any non-cancelled row.
    'would_be_admitted_by_current_predicate',
      (select count(*) from classified where bucket not in ('no_verified_case', 'no_current_notice',
                                                            'cancelled'))
  ) into v_out;

  return v_out;
end $function$;
revoke execute on function public.owner_notice_release_readiness_census() from public, anon;
grant  execute on function public.owner_notice_release_readiness_census() to authenticated;

comment on function public.owner_notice_release_readiness_census() is
  'Read-only Phase 11-OC blast-radius projection: how many estates standing at the release door '
  'would be admitted or refused by the Phase D acceptance predicate, classified by the state of the '
  'CURRENT generation of the CURRENT case episode. Scoped by case exactly as the Phase D predicate '
  'is, so it cannot credit an accepted notice from a prior rejected process. Every estate lands in '
  'one NAMED bucket and the buckets reconcile against the total. Counts ONLY — no estate id, no '
  'case id, no user id, no recipient address, on any branch. Admin-gated.';


-- ==== db/functions/operator_console.sql ===========================================================
-- ════════════════════════════════════════════════════════════════════════════════════════════════
-- PHASE 11-K · OPERATOR PROJECTIONS — the two READ doors that make nine deployed WRITE doors usable
-- ════════════════════════════════════════════════════════════════════════════════════════════════
--
-- ★ WHY THIS FILE EXISTS AT ALL. Phase 11 deployed nine admin-gated write routines and not one way
-- to see what they act on. `death_verification_cases`, `death_verification_evidence` and
-- `estate_lifecycle` were created with ZERO grants and ZERO policies (0052 asserts exactly that),
-- and no `admin_list_*`/`admin_get_*` routine was ever written for them. The consequence is sharper
-- than "unbound": an operator holding a valid AAL2 admin JWT can DECIDE a case, but has no way to
-- learn a case id, so there is nothing they can name. The lifecycle was unreachable by anyone.
--
-- ★ NOTHING HERE CREATES AUTHORITY. Both routines are STABLE reads behind the same
-- `admin_require_gate()` every other admin door uses — auth → is_admin → AAL2 → 15-minute freshness,
-- INSIDE the definer (the DEFINER-door discipline: a direct PostgREST caller hits the identical
-- checks, and the console buys no privilege the raw door does not already give). No lifecycle
-- moves, no level changes, no case is decided, no notice dispatches, no window opens, nothing
-- releases. Every one of those remains the deployed routine's own decision.
--
-- ★ AND THIS IS NOT AN ADMIN ESTATE DUMP. Administrative workflow authority and estate-content
-- disclosure are separate axes, and least disclosure applies to operators too. These projections
-- answer about the VERIFICATION WORKFLOW and carry, in neither routine:
--
--     no asset, no valuation, no net worth        no beneficiary, no membership roster
--     no designation list                          no access grant, no visibility tier
--     no document bytes, no storage path           no signed URL
--     no encrypted instruction                     NO OWNER EMAIL ADDRESS
--
-- The full field-by-field justification, with sensitivity and retention, is
-- `docs/phase11k-disclosure-census.md`. `test/operatorProjectionDisclosure.test.ts` pins the
-- absences against this source text with positive controls, so a future edit that adds one of them
-- fails rather than ships.
--
-- Source of truth — re-apply on DB reset. Deploys with `db/bundles/operator_console_bundle.sql`,
-- after migration 0056.

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- admin_list_death_verification_cases(...) → table                            [admin, AAL2+fresh]
-- ────────────────────────────────────────────────────────────────────────────────────────────────
--
-- THE OPERATOR QUEUE. What an operator needs to triage a list of cases, and nothing else.
--
-- ★ NO OWNER EMAIL, AND `owner_channel_resolvable` INSTEAD. The operator's workflow question is
-- "will dispatch succeed for this estate", not "what is this living person's address". The boolean
-- answers the first exactly and the second not at all — and `dispatch_owner_safety_notice` resolves
-- the real address itself, from `auth.users`, where no claimant can repoint it. An operator never
-- needs to see it, so this projection never has it to leak. A console that displayed the address
-- "for confirmation" would be a permanent, searchable copy of a living owner's contact detail in a
-- surface whose whole premise is that this person may be the victim of a false claim.
--
-- ★ THE REQUIRED LEVEL IS RE-DERIVED LIVE, matching `admin_decide_death_verification_case` exactly.
-- `required_level_at_initiation` is a record of what policy said when the case opened; showing THAT
-- as the bar would mislead whenever policy tightened mid-case — and the decision routine would then
-- refuse a `verify` the console had just shown as permitted. The console must not be able to
-- disagree with the door.
--
-- ★ INITIATOR IDENTITY IS WITHHELD HERE and disclosed only in the case file, where adjudicating a
-- specific claim actually requires it. A queue needs to know a case exists; it does not need to
-- name the person who opened it.
create or replace function public.admin_list_death_verification_cases(
  p_status           text        default null,
  p_before_initiated timestamptz default null,
  p_before_id        uuid        default null,
  p_limit            int         default 50
)
 returns table(
   case_id                  uuid,
   estate_id                uuid,
   estate_name              text,
   case_status              text,
   lifecycle_state          text,
   event_type               text,
   initiated_at             timestamptz,
   updated_at               timestamptz,
   initiator_capacity       text,
   jurisdiction_context     text,
   required_level           text,
   attained_level           text,
   evidence_total           int,
   evidence_awaiting_review int,
   owner_channel_resolvable boolean,
   decided_at               timestamptz
 )
 language plpgsql
 security definer
 stable
 set search_path to 'public'
as $function$
declare v_limit int;
begin
  perform public.admin_require_gate();
  -- The admin_list_claim_packets_enriched clamp, verbatim: a caller cannot ask for the whole table.
  v_limit := least(greatest(coalesce(p_limit, 50), 1), 200);

  return query
    select
      c.id,
      c.estate_id,
      e.name,
      c.status,
      -- An estate with no lifecycle row has never entered the machine; `active` is the same default
      -- `apply_estate_lifecycle_transition` and `estate_lifecycle_state` both use.
      coalesce(l.state, 'active'),
      c.event_type,
      c.created_at,
      c.updated_at,
      c.initiator_capacity,
      c.jurisdiction_context,
      public.required_verification_level(c.estate_id)::text,
      c.attained_level::text,
      coalesce(ev.total, 0)::int,
      coalesce(ev.awaiting, 0)::int,
      exists (
        select 1 from auth.users u
         where u.id = public.estate_owner_user_id(c.estate_id)
           and btrim(coalesce(u.email, '')) <> ''
      ),
      c.decided_at
    from public.death_verification_cases c
    left join public.estates e on e.id = c.estate_id
    left join public.estate_lifecycle l on l.estate_id = c.estate_id
    left join lateral (
      -- ★ A LATERAL AGGREGATE, NOT A JOINED GROUP BY. The 11-F census learned this the expensive
      -- way: a per-status GROUP BY joined laterally onto the row set multiplies rows, and the
      -- headline number silently triples. Scoped to `x.case_id = c.id`, this returns one row.
      select count(*)::int as total,
             count(*) filter (where x.review_status = 'received')::int as awaiting
        from public.death_verification_evidence x
       where x.case_id = c.id
    ) ev on true
   where (p_status is null or c.status = p_status)
     and (p_before_initiated is null
          or (c.created_at, c.id) < (p_before_initiated, coalesce(p_before_id, c.id)))
   order by c.created_at desc, c.id desc
   limit v_limit;
end $function$;
revoke execute on function public.admin_list_death_verification_cases(text, timestamptz, uuid, int)
  from public, anon;
grant  execute on function public.admin_list_death_verification_cases(text, timestamptz, uuid, int)
  to authenticated;

comment on function public.admin_list_death_verification_cases(text, timestamptz, uuid, int) is
  'The operator queue for death-verification cases (Phase 11-K). Workflow facts only: case status, '
  'lifecycle state, LIVE required level vs attained, evidence counts, and whether the owner channel '
  'RESOLVES — never the owner address. No asset, valuation, beneficiary, designation, grant, '
  'document byte or storage path. Admin-gated inside the definer; keyset paged; clamped to 200.';

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- admin_get_death_verification_case(p_case) → jsonb                           [admin, AAL2+fresh]
-- ────────────────────────────────────────────────────────────────────────────────────────────────
--
-- THE CASE FILE. Everything the six lifecycle decisions actually turn on, assembled in ONE call so
-- the console cannot compose a wider view out of several narrow ones — and so there is a single
-- place to audit what an operator may see.
--
-- ★ `viewer_is_reviewer_a` IS DERIVED FROM auth.uid() INSIDE THIS DEFINER. That is the whole reason
-- it lives here rather than in the client. The console must be able to state that the signed-in
-- operator is ineligible to authorize this release; a client that computed it by comparing two
-- values it was handed could be made to compute it wrongly, and the failure would be silent and in
-- the operator's favour. The server answers it, the client renders it, and `authorize_release`
-- re-derives reviewer_a and re-checks distinctness independently regardless. This field makes the
-- affordance TRUTHFUL; it grants nothing. UI affordance is not permission.
--
-- ★ WINDOW FACTS ARE FACTS, NOT A COUNTDOWN. `release_eligible_at` and `elapsed` are what an
-- operator needs in order to know whether a release call will be refused. The duration is read LIVE
-- through `challenge_window_duration()`, the same way `authorize_release` reads it, so the console
-- cannot display a deadline the routine disagrees with. `elapsed` uses STRICT `>` for the same
-- reason the routine does: at the exact boundary instant release refuses and the owner's challenge
-- still succeeds, and a console that rounded the other way would offer an action that is refused.
-- Nothing here ranks, scores, urges, estimates, or performs urgency.
--
-- ★ DECISION AND REVIEW NOTES ARE INCLUDED, AS A WORKFLOW REQUIREMENT RATHER THAN A CONVENIENCE.
-- The second reviewer must form an independent judgement about what the FIRST reviewer concluded; a
-- two-person rule where reviewer B cannot read reviewer A's reasoning is a rubber stamp with extra
-- steps. These are operator-authored notes about a case, never estate content.
--
-- ★ REFUSAL SHAPE DIFFERS FROM THE CLIENT DOORS, DELIBERATELY. The client routines answer one
-- sentinel for missing-and-foreign alike, because case existence is itself protected from a probing
-- claimant (T9). An authenticated platform admin behind AAL2 + freshness is authorized to know that
-- a case does not exist — the same latitude `admin_review_death_evidence` already takes with
-- `evidence_not_found`. Copying the client's indistinguishability here would hide operator typos,
-- not protect anyone.
create or replace function public.admin_get_death_verification_case(p_case uuid)
 returns jsonb
 language plpgsql
 security definer
 stable
 set search_path to 'public'
as $function$
declare
  v_uid      uuid;
  v_c        public.death_verification_cases%rowtype;
  v_l        public.estate_lifecycle%rowtype;
  v_duration interval;
  v_out      jsonb;
begin
  perform public.admin_require_gate();
  v_uid := auth.uid();

  select * into v_c from public.death_verification_cases c where c.id = p_case;
  if not found then
    raise exception 'case_not_found' using errcode = 'P0002';
  end if;

  select * into v_l from public.estate_lifecycle l where l.estate_id = v_c.estate_id;
  v_duration := public.challenge_window_duration();

  select jsonb_build_object(
    'case', jsonb_build_object(
      'case_id',              v_c.id,
      'estate_id',            v_c.estate_id,
      'estate_name',          (select e.name from public.estates e where e.id = v_c.estate_id),
      'status',               v_c.status,
      'event_type',           v_c.event_type,
      'initiated_at',         v_c.created_at,
      'updated_at',           v_c.updated_at,
      'initiator_capacity',   v_c.initiator_capacity,
      'jurisdiction_context', v_c.jurisdiction_context,
      -- BOTH levels, both labelled. The live value is the bar the decision routine will apply; the
      -- snapshot is the case file's record of what policy said at initiation. Showing only one of
      -- them is how a console and a decision routine come to disagree in front of an operator.
      'required_level_at_initiation', v_c.required_level_at_initiation::text,
      'required_level_live',  public.required_verification_level(v_c.estate_id)::text,
      'attained_level',       v_c.attained_level::text,
      'decided_at',           v_c.decided_at,
      'decision_note',        v_c.decision_note
    ),
    -- Initiator identity: disclosed HERE and not in the queue, because adjudicating THIS case is
    -- the workflow that needs it — an operator judging whether a claimed fiduciary is legitimate.
    'initiator', jsonb_build_object(
      'user_id',  v_c.initiated_by,
      'email',    (select p.email     from public.profiles p where p.id = v_c.initiated_by),
      'name',     (select p.full_name from public.profiles p where p.id = v_c.initiated_by),
      'capacity', v_c.initiator_capacity
    ),
    'lifecycle', jsonb_build_object(
      'state',                       coalesce(v_l.state, 'active'),
      'owner_notified_at',           v_l.owner_notified_at,
      'challenge_window_started_at', v_l.challenge_window_started_at,
      'halted_at',                   v_l.halted_at,
      'released_at',                 v_l.released_at,
      'updated_at',                  v_l.updated_at
    ),
    'window', jsonb_build_object(
      'duration',            v_duration::text,
      -- NULL duration means NOT CONFIGURED, which means the window never elapses and release
      -- refuses. The console must be able to say that, rather than render a blank date.
      'configured',          v_duration is not null,
      'release_eligible_at', case when v_l.owner_notified_at is not null and v_duration is not null
                                  then v_l.owner_notified_at + v_duration end,
      'elapsed',             coalesce(now() > v_l.owner_notified_at + v_duration, false)
    ),
    -- ────────────────────────────────────────────────────────────────────────────────────────
    -- ★ PHASE 11-OC — THE EPISODE, NOT JUST A LIST OF ROWS.
    -- ────────────────────────────────────────────────────────────────────────────────────────
    --
    -- Phase A gave a notice an episode (`case_id`), a position in it (`generation`), a retirement
    -- link (`superseded_by`) and the one fact release turns on (`notice_accepted_at`). Without those
    -- four the console can render only a status — and a status is precisely what this phase proved is
    -- not enough: `dispatched` means "provider accepted" for a row written after Phase A and means
    -- "we do not know" for a row written before it. A console that labelled both the same way would
    -- state, on the one screen where it matters, that a living owner was reached when nobody knows.
    --
    -- `is_current` is projected rather than left to the client to derive from `superseded_by`,
    -- because a retired generation and a live one must never be shown with the same weight, and a
    -- null-check is exactly the kind of derivation a UI gets wrong once and then keeps.
    --
    -- ★ STILL NO ADDRESS. `recipient` is NOT selected, here or anywhere in this file. An operator's
    -- workflow never requires a living owner's address, and a projection that never carries it cannot
    -- leak it through a log, a screenshot, or a future console feature. Every field added here is a
    -- workflow fact about a queue row; none of them is contact detail.
    'owner_notice', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id',            o.id,
               'channel',       o.channel,
               'notice_kind',   o.notice_kind,
               'status',        o.status,
               'requested_at',  o.requested_at,
               'dispatched_at', o.dispatched_at,
               'attempts',      o.attempts,
               'failure_class', o.failure_class,
               -- The episode this row belongs to. NULL on a pre-Phase-A row, which is the honest
               -- answer: those belong to no provable episode and are never guessed into one.
               'case_id',            o.case_id,
               'generation',         o.generation,
               'superseded_by',      o.superseded_by,
               'is_current',         o.superseded_by is null,
               -- THE FACT. NULL is a real answer and the console must render it as one.
               'notice_accepted_at', o.notice_accepted_at,
               'claimed_at',         o.claimed_at
             ) order by o.requested_at desc)
        from public.owner_notice_outbox o
       where o.estate_id = v_c.estate_id
    ), '[]'::jsonb),
    -- ────────────────────────────────────────────────────────────────────────────────────────
    -- ★ PHASE 11-OC / PHASE C — ACTION AVAILABILITY IS THE SERVER'S ANSWER, NOT THE CLIENT'S GUESS.
    -- ────────────────────────────────────────────────────────────────────────────────────────
    --
    -- The console must offer "Re-send owner safety notice" exactly when
    -- `reissue_owner_safety_notice` would accept it. The eligibility rule is not a status list — it
    -- turns on the lifecycle state, on whether this case is still the CURRENT episode, on the
    -- acceptance FACT (not the status), and on whether an address resolves. A TypeScript mirror of
    -- that would be a second policy, and the first time the two drifted an operator would either be
    -- offered a control the door refuses or denied one an estate needs.
    --
    -- So the verdict comes from `owner_notice_reissue_assessment`, the SAME function the door
    -- consults, and the console renders it. This is the `viewer_is_reviewer_a` discipline applied to
    -- an action: the server answers, the client displays, and the routine re-checks independently
    -- regardless. UI affordance is not permission — this grants nothing.
    --
    -- It carries a NAMED refusal code rather than a sentence, so the console owns the operator copy
    -- and the server owns the policy. Counts and codes only; no address on any branch.
    'owner_notice_reissue', public.owner_notice_reissue_assessment(v_c.id),
    'evidence', coalesce((
      select jsonb_agg(jsonb_build_object(
               'evidence_id',   x.id,
               'document_id',   x.document_id,
               'title',         d.title,
               'doc_type',      d.doc_type,
               'uploaded_at',   d.created_at,
               'submitted_at',  x.submitted_at,
               'review_status', x.review_status,
               'reviewed_at',   x.reviewed_at,
               'review_note',   x.review_note
               -- No storage_path, no bytes, no signed URL. Evidence BYTES have their own separately
               -- gated door (the admin_authorize_claim_evidence pattern); metadata is what a review
               -- queue needs, and the two must not be conflated into one projection.
             ) order by x.submitted_at)
        from public.death_verification_evidence x
        left join public.documents d on d.id = x.document_id
       where x.case_id = v_c.id
    ), '[]'::jsonb),
    'release', jsonb_build_object(
      -- reviewer_a is the case DECIDER, derived exactly as authorize_release derives it. NULL until
      -- the case is decided — there is no first reviewer before there is a decision.
      'reviewer_a',           v_c.decided_by,
      'viewer_is_reviewer_a', v_c.decided_by is not null and v_c.decided_by = v_uid,
      'authorized', (
        select jsonb_build_object('authorized_at', ra.authorized_at,
                                  'reviewer_a',    ra.reviewer_a,
                                  'reviewer_b',    ra.reviewer_b,
                                  'audit_reason',  ra.audit_reason)
          from public.release_authorizations ra
         where ra.estate_id = v_c.estate_id
         order by ra.authorized_at desc
         limit 1
      )
    )
  ) into v_out;

  return v_out;
end $function$;
revoke execute on function public.admin_get_death_verification_case(uuid) from public, anon;
grant  execute on function public.admin_get_death_verification_case(uuid) to authenticated;

comment on function public.admin_get_death_verification_case(uuid) is
  'The operator case file (Phase 11-K): case facts, initiator identity, lifecycle timestamps, LIVE '
  'window facts, owner-notice dispatch status (NEVER the recipient address) and evidence METADATA. '
  'viewer_is_reviewer_a is derived from auth.uid() INSIDE this definer so the console can state '
  'release ineligibility truthfully — it grants nothing; authorize_release re-checks independently. '
  'Carries no asset, valuation, beneficiary, designation, grant, document byte or storage path.';

commit;
